/**
 * Icon — renders a 24px glyph. Inherits color via currentColor.
 */
export function Icon({ name, size = 24, color, style, className, ...rest }) {
  const inner = FILL_ICONS[name] != null ? FILL_ICONS[name] : (LINE_ICONS[name] != null ? LINE_OPEN + LINE_ICONS[name] + LINE_CLOSE : undefined);
  if (!inner) {
    return React.createElement("svg", { width: size, height: size, viewBox: "0 0 24 24", style, className, ...rest });
  }
  return React.createElement("svg", {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "currentColor",
    role: "img",
    "aria-label": name,
    className,
    style: { display: "block", color, flexShrink: 0, ...style },
    dangerouslySetInnerHTML: { __html: inner },
    ...rest,
  });
}

export default Icon;
